describe('Background Sync Toast Notification', () => {
  beforeEach(() => {
    cy.visit('/sync-page');
  });

  it('should display toast notification when background sync completes successfully', () => {
    // Trigger background sync
    cy.intercept('POST', '/api/sync/start').as('startSync');
    cy.get('[data-testid="start-sync-button"]').click();
    cy.wait('@startSync');

    // Wait for sync to complete
    cy.intercept('POST', '/api/sync/complete').as('completeSync');
    cy.wait('@completeSync');

    // Verify toast notification appears
    cy.get('[data-testid="toast-container"]').should('be.visible');
    cy.get('[data-testid="toast-message"]').should('contain', 'Background sync completed');
    cy.get('[data-testid="toast-duration"]').should('contain', '3 seconds');

    // Verify toast is removed after duration
    cy.get('[data-testid="toast-container"]').should('not.exist');
  });

  it('should display error toast notification when background sync fails', () => {
    // Trigger background sync
    cy.intercept('POST', '/api/sync/start').as('startSync');
    cy.get('[data-testid="start-sync-button"]').click();
    cy.wait('@startSync');

    // Simulate sync failure
    cy.intercept('POST', '/api/sync/complete', {
      statusCode: 500,
      body: { error: 'Internal server error' }
    }).as('failedSync');
    cy.wait('@failedSync');

    // Verify error toast notification appears
    cy.get('[data-testid="toast-container"]').should('be.visible');
    cy.get('[data-testid="toast-message"]').should('contain', 'Background sync failed');
    cy.get('[data-testid="toast-duration"]').should('contain', '3 seconds');

    // Verify error toast is removed after duration
    cy.get('[data-testid="toast-container"]').should('not.exist');
  });
});
